import {steps,shift} from './shift.mjs';
import {names,lessons,ratio,config,observation} from './config.mjs';
import {search} from './search.mjs';
import {tracks} from '../learn/content.mjs';
import {catalog} from '../concepts/catalog.mjs';
const $=id=>document.getElementById(id),p=new URLSearchParams(location.search),en=p.get('lang')==='en',l=en?'en':'es',t=(a,b)=>en?b:a,lab=location.pathname.endsWith('lab.html'),url=(page,k)=>page+'?lang='+l+'&stage='+k;
let k=Math.min(5,Math.max(0,parseInt(p.get('stage'))||0));if(!lab&&!p.has('stage'))k=4;
let step=0,apart=false;
let front=false,v=0,rig=null,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,a=0,prev=0,visible=true;
document.documentElement.lang=l;document.title=(lab?t('Banco de piñonería','Gear train bench'):t('Atlas de mecanismos','Atlas of mechanisms'))+' · Mecánica Lab';
function link(id,txt,path){$(id).textContent=txt;$(id).href=path}
link('courses',t('Cursos','Courses'),'index.html?lang='+l+'#shelf');link('labs',t('Laboratorios','Labs'),'lab.html?lang='+l);link('language',en?'ES':'EN',location.pathname+'?stage='+k+'&lang='+(en?'es':'en'));$('find').textContent=t('Buscar','Search')+'　⌘K';search($('find'),en);
$('sub').textContent=lab?t('Laboratorio / transmisión','Lab / transmission'):t('Biblioteca técnica　/　Vol. 01','Technical library　/　Vol. 01');$('title').textContent=lab?t('Banco de piñonería','Gear train bench'):t('Atlas de mecanismos','Atlas of mechanisms');$('intro').textContent=lab?t('Gira la vista arrastrando el banco. Cambia una condición y sigue la pieza de salida.','Drag to orbit the bench. Change one condition and follow the output member.'):t('Aprende mecánica siguiendo el movimiento. Empieza con un diente y termina eligiendo una marcha.','Learn mechanics by following motion. Start with one tooth and finish by selecting a gear.');$('plate').textContent='ANATOMY　/　'+t('BANCO CINEMÁTICO','KINEMATIC BENCH');$('ins').textContent=t('Inspector　/　cómo funciona','Inspector　/　how it works');$('routeLabel').textContent=t('Del diente a la caja','From tooth to transmission');$('libraryLabel').textContent=lab?t('Más bancos para explorar','More benches to explore'):t('Biblioteca de cursos','Course library');
function tile(parent,n,title,href,desc=''){const b=document.createElement('a');b.href=href;b.className='tile';const s=document.createElement('span');s.className='number';s.textContent=n;const strong=document.createElement('strong');strong.textContent=title;b.append(s,strong);if(desc){const p=document.createElement('p');p.textContent=desc;b.append(p)}parent.append(b);return b}
names.forEach((n,i)=>{let b=tile($('route'),'0'+(i+1)+' / 06',n[+en],url('lab.html',i));if(lab)b.onclick=e=>{if(e.ctrlKey||e.metaKey)return;e.preventDefault();k=i;history.replaceState(null,'',url('lab.html',k));reset();$('stage').scrollIntoView({block:'center'})}});
if(lab){for(const [id,c] of Object.entries(catalog))tile($('shelf'),'LAB · ES',c.title,'../concepts/index.html?id='+id)}else{tracks.forEach((tr,i)=>tile($('shelf'),'0'+(i+1)+'　/　ES + EN',tr.name[l],'../learn/index.html?lang='+l+'&track='+tr.id,tr.intro[l]));for(const [n,href] of [['Automotriz','../autos/index.html'],['Bicicletas','../bikes/index.html'],['Física y mecatrónica','../index.html#curso']])tile($('shelf'),'ES',n,href)}
function update(){$('view').textContent=front?t('Vista oblicua','Oblique view'):t('Vista frontal','Front view');const [eq,why]=observation(k,v,en);$('traceLabel').textContent=t('Sigue el movimiento　/　modelo ideal sin pérdidas','Trace the motion　/　ideal lossless model');$('formula').textContent=eq;$('trace').textContent=why;const rpm=+$('rpm').value,q=ratio(k,v);$('speed').textContent=t('Entrada','Input')+'　'+rpm+' rpm';$('m1').textContent=k===0?t('Radio','Radius'):t('Salida','Output');$('v1').textContent=k===0?[20,40,60][v]+' mm':k===5&&!v?'—':(q*rpm).toLocaleString(l,{maximumFractionDigits:1})+' rpm';$('m2').textContent=k===0?t('Fuerza tangencial','Tangential force'):t('Par ideal · entrada 6 N·m','Ideal torque · 6 N·m input');$('v2').textContent=k===0?300/(v+1)+' N':(q?6/Math.abs(q):0).toLocaleString(l,{maximumFractionDigits:1})+' N·m';$('play').textContent=playing?t('Ⅱ　Pausar','Ⅱ　Pause'):t('▷　Animar','▷　Play');$('legend').textContent=k===0?t('Flecha ámbar: fuerza tangencial','Amber arrow: tangential force'):t('Cian: entrada　·　Ámbar: salida　·　−: giro contrario','Cyan: input　·　Amber: output　·　−: opposite rotation');guide()}
function rebuild(){rig?.setup(k,v,{step:v?step:-1,apart});if(front)rig?.view(true,k)}
function guide(){
 $('shiftGuide').hidden=k!==5;if(k!==5)return;
 link('slowLink',t('▷ Cámara lenta · de primera a segunda','▷ Slow motion · first to second'),'upshift.html?lang='+l);
 const st=shift(v,step);
 const labels=en?['Flywheel','Cone ring','Sliding sleeve','Clutch disc','Input shaft','Gear mesh','Splined hub','Output flange']:['Volante','Anillo de sincronización','Manguito','Disco de embrague','Eje primario','Contacto entre dientes','Cubo estriado','Brida de salida'];rig?.label(v?labels[step]:t('Salida libre','Free output'));
 $('explode').textContent=apart?t('Rearmar caja','Reassemble'):t('Ver despiece 3D','Explode gearbox');$('explode').setAttribute('aria-pressed',String(apart));
 $('shiftCount').textContent=v?t('Cambio · paso ','Shift · step ')+(step+1)+' / '+steps.length:t('Punto muerto','Neutral');
 $('shiftTitle').textContent=v?steps[step][+en]:t('Ninguna marcha acoplada','No gear engaged');
 $('shiftText').textContent=v?steps[step][2+(+en)]:t('El embrague está cerrado y el primario gira, pero ambos manguitos están centrados. Elige una marcha para seguir el cambio.','The clutch is closed and the input turns, but both sleeves are centred. Select a gear to follow the shift.');
 $('backStep').textContent=t('← Anterior','← Previous');$('nextStep').textContent=t('Siguiente →','Next →');$('backStep').disabled=!v||step===0;$('nextStep').disabled=!v||step===steps.length-1;
 $('v2').textContent=st.torque.toLocaleString(l,{maximumFractionDigits:1})+' N·m';
 $('traceLabel').textContent=t('Ruta del par motor','Engine torque path');
 $('formula').textContent=!v?t('Primario → ruedas libres ∥ salida','Input → free gears ∥ output'):!st.closed?t('Motor → volante ∥ disco','Engine → flywheel ∥ disc'):t('Motor → embrague → primario → pareja → cubo → salida','Engine → clutch → input → gear pair → hub → output');
 $('trace').textContent=apart?t('Despiece estático: la separación axial sirve para identificar las piezas; no son holguras de trabajo.','Static exploded view: axial spacing identifies parts; it is not operating clearance.'):t('Cambio ilustrativo con el vehículo rodando. Las rpm de salida se mantienen por inercia durante el cambio. El par indicado es el del motor entregado a la salida; se omiten pérdidas y transitorios.','Illustrative rolling shift. Output speed coasts during the shift. The readout is engine torque delivered to the output; losses and transients are omitted.');
 $('play').disabled=apart||!rig;$('legend').textContent=t('Ámbar: pieza del paso　·　Bronce: anillos','Amber: current step　·　Brass: rings');
 $('speed').textContent=t('Motor','Engine')+'　'+$('rpm').value+' rpm';
}
function walk(n){step=n;rebuild();update()}
$('backStep').onclick=()=>walk(Math.max(0,step-1));$('nextStep').onclick=()=>walk(Math.min(steps.length-1,step+1));$('explode').onclick=()=>{apart=!apart;rebuild();update()};
function reset(){step=0;apart=false;front=false;$('play').disabled=false;v=[0,1,1,0,0,1][k];a=0;const [label,opts]=config(k,v,en);$('param').textContent=label;$('setting').replaceChildren(...opts.map((s,i)=>new Option(s,i)));$('setting').value=v;$('code').textContent='FIG. 0'+(k+1)+' / 06';$('name').textContent=names[k][+en];$('copy').textContent=lessons[k][+en];link('action',lab?(k<5?t('Siguiente mecanismo →','Next mechanism →'):t('Volver a los cursos →','Back to courses →')):t('Abrir laboratorio →','Open laboratory →'),lab&&k===5?'index.html?lang='+l:url('lab.html',lab?k+1:k));link('language',en?'ES':'EN',location.pathname+'?stage='+k+'&lang='+(en?'es':'en'));[...$('route').children].forEach((b,i)=>b.setAttribute('aria-current',String(i===k)));rebuild();update()}
$('setting').onchange=()=>{v=+$('setting').value;a=0;step=0;front=false;rebuild();update()};$('view').onclick=()=>{front=!front;rig?.view(front,k);update()};$('rpm').oninput=update;$('play').onclick=()=>{playing=!playing;update()};reset();
try{rig=(await import('./model.mjs')).bench($('stage'));rebuild();update();new IntersectionObserver(es=>visible=es[0].isIntersecting).observe($('stage'));function frame(now){if(!document.hidden&&visible){if(playing&&!apart)a+=Math.min((now-prev)/1000,.05)*+$('rpm').value*Math.PI/30;rig.draw(a)}prev=now;requestAnimationFrame(frame)}requestAnimationFrame(frame)}catch(err){$('stage').textContent=t('La vista 3D requiere WebGL. Puedes explorar las relaciones con los controles.','The 3D view requires WebGL. You can explore the ratios using the controls.');$('play').disabled=true;$('view').disabled=true;console.warn(err)}
